personas = {"juan": {"edad": 30}, "ana": {"edad": 28}}
relaciones = [("juan", "FRIEND", "ana")]

def match_friend(nombre):
    # Simula: MATCH (p:Person)-[:FRIEND]->(friend) WHERE p.name = nombre RETURN friend
    return [b for a, rel, b in relaciones if a == nombre and rel == "FRIEND"]

def crear_persona(nombre, edad):
    # Simula: CREATE (p:Person {name: nombre, age: edad})
    personas[nombre] = {"edad": edad}

def actualizar_edad(nombre, nueva_edad):
    # Simula: MATCH (p:Person {name: nombre}) SET p.age = nueva_edad
    personas[nombre]["edad"] = nueva_edad

crear_persona("marta", 40)
print(f"Amigos de juan: {match_friend('juan')}")
actualizar_edad("juan", 31)
print(f"Edad de juan tras SET: {personas['juan']['edad']}")
print(f"Personas registradas: {sorted(personas)}")
